import { EXTRA_CITIES } from './cityExtra.js'
CITIES.push(...EXTRA_CITIES)
export const CITY_BY_ID = {}
for (const c of CITIES) CITY_BY_ID[c.id] = c
export const HOME_CITY = CITY_BY_ID['india_delhi']
export function cityOf(id) { return CITY_BY_ID[id] || HOME_CITY }
export function cityNameOf(id) { const c = CITY_BY_ID[id]; return c ? c.name : 'Delhi' }
export function citiesOfCountry(country) { return CITIES.filter((c) => c.country === country) }
export function countriesOfCities(ids) { return [...new Set((ids || []).map((id) => (CITY_BY_ID[id] || {}).country).filter(Boolean))] }
export const RIVAL_HOMES = { 'Simran (Mall Mogul)': 'Mumbai', 'Vikram (Startup Bhai)': 'Bengaluru', 'Ananya (Property Tycoon)': 'Gurgaon', 'Rohit (Stock Shark)': 'Mumbai (BKC)', 'Priya (Café Queen)': 'Pune', 'Sharma Ji (Kirana King)': 'Delhi' }
export function demandOf(city, cat) { if (!city) return 1; return (city.dem || 1) * ((city.boost || {})[cat] || 1) }
